import django.db.models.deletion
from datetime import date, timedelta

from django.db import migrations, models
from django.utils.text import slugify


def existing_restaurants_keep_working(apps, schema_editor):
    # restaurants from before plans existed stay open for a year, and get a booking slug
    Restaurant = apps.get_model("core", "Restaurant")
    taken = set()
    for r in Restaurant.objects.all():
        base = slugify(r.name)[:50] or "restaurant"
        slug, n = base, 2
        while slug in taken:
            slug, n = f"{base}-{n}", n + 1
        taken.add(slug)
        r.slug, r.paid_until = slug, date.today() + timedelta(days=365)
        r.save(update_fields=["slug", "paid_until"])



